// The shop's pictures on the desktop: the layers in sight, the badge wall and
// progress bars, each an SVG document an Svg element draws. The terminal
// draws the same in text. Their greys are see-through, so they read on a light
// theme as on a dark one, and each is built only when what it shows changes.

import type { Badge, BadgeArt, ShopModel } from '../types'
import { iconBody } from './icons.ts'

/** The width the shop's pictures are drawn at; a narrower pane scales them down. */
export const PICTURE_WIDTH = 484

const GREY_FILL = 'rgba(128,128,128,.12)'
const GREY_LINE = 'rgba(128,128,128,.38)'
const GOLD = '#f2b632'
/** The color a pointer over a badge rings it in: the Claude orange. */
const HOVER = '#d97757'

const esc = (text: string): string => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

/** An SVG document; the color scheme lets a frame that draws it stay see-through on either theme. */
const svg = (width: number, height: number, body: string): string =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" style="color-scheme:light dark">${body}</svg>`

/** A bar `share` full in `color`, rounded at both ends. */
export function barSvg(share: number, color: string, width = PICTURE_WIDTH, height = 10): string {
  const filled = Math.round(Math.max(0, Math.min(1, share)) * width)
  const r = height / 2
  return svg(
    width,
    height,
    `<clipPath id="c"><rect width="${width}" height="${height}" rx="${r}"/></clipPath>` +
      `<g clip-path="url(#c)"><rect width="${width}" height="${height}" fill="${GREY_FILL}"/>` +
      (filled > 0 ? `<rect width="${filled}" height="${height}" fill="${color}"/>` : '') +
      '</g>',
  )
}

/**
 * The layers in sight as a row of blocks: the reached ones in their colors,
 * the one the mine is in ringed, the next one dashed, the ones below empty.
 */
export function strataSvg(strata: ShopModel['depth']['strata'], width = PICTURE_WIDTH): string {
  const pad = 4
  const height = 22
  const gap = 4
  const n = Math.max(1, strata.length)
  const w = (width - 2 * pad - gap * (n - 1)) / n
  const blocks = strata.map((s, i) => {
    const x = pad + i * (w + gap)
    const rect = (extra: string) => `<rect x="${x.toFixed(1)}" y="${pad}" width="${w.toFixed(1)}" height="${height}" rx="5" ${extra}/>`
    switch (s.state) {
      case 'reached':
        return rect(`fill="${s.color}"`)
      case 'here':
        return (
          rect(`fill="${s.color}"`) +
          `<rect x="${(x - 3).toFixed(1)}" y="${pad - 3}" width="${(w + 6).toFixed(1)}" height="${height + 6}" rx="7.5" fill="none" stroke="${s.color}" stroke-width="1.5"/>`
        )
      case 'next':
        return rect(`fill="${s.color}" fill-opacity=".12" stroke="${s.color}" stroke-width="1.5" stroke-dasharray="4 3"`)
      case 'ahead':
        return rect(`fill="none" stroke="${GREY_LINE}" stroke-width="1"`)
    }
  })
  return svg(width, height + 2 * pad, blocks.join(''))
}

const TILE = 40
const GAP = 7
/** Badges to a row: nine, as many as the depth, Claude's work and the secrets each have. */
const PER_ROW = 9
/** The wall's width: nine badges to a row, narrower than the pane so it never overflows it. */
export const WALL_WIDTH = PER_ROW * (TILE + GAP) - GAP

/** A lump of a layer's rock, 12 x 12: the layer's color with darker flecks. */
const ROCK = [
  '............',
  '....KKKK....',
  '..KKccccKK..',
  '.KccdcccccK.',
  '.KcccccdccK.',
  '.KcdccccccK.',
  '.KccccdcccK.',
  '.KcccccccdK.',
  '..KKccccKK..',
  '....KKKK....',
  '............',
  '............',
]

/** A color `k` of the way to black. */
function darker(hex: string, k: number): string {
  const n = parseInt(hex.slice(1), 16)
  const ch = [n >> 16, (n >> 8) & 255, n & 255].map(v => Math.round(v * (1 - k)))
  return `#${ch.map(v => v.toString(16).padStart(2, '0')).join('')}`
}

function rockBody(color: string): string {
  const fill: Record<string, string> = { K: '#1d1512', c: color, d: darker(color, 0.35) }
  let body = ''
  ROCK.forEach((row, y) => {
    for (let x = 0; x < row.length; x += 1) {
      const c = fill[row[x] ?? '.']
      if (c !== undefined) body += `<rect x="${x}" y="${y}" width="1" height="1" fill="${c}"/>`
    }
  })
  return body
}

/** The symbol a badge's picture is drawn from, added to `used` the first time. */
function symbolOf(art: BadgeArt, used: Map<string, string>): string {
  const id = art.kind === 'icon' ? `i-${art.id}` : `r-${art.color.slice(1)}`
  if (!used.has(id)) used.set(id, art.kind === 'icon' ? iconBody(art.id) : rockBody(art.color))
  return id
}

function tile(b: Badge, i: number, x: number, y: number, used: Map<string, string>): string {
  const kind = b.isEarned ? 'b won' : b.isSurprise ? 'b q' : 'b'
  const frame = `<rect class="f" x="${x + 0.75}" y="${y + 0.75}" width="${TILE - 1.5}" height="${TILE - 1.5}" rx="8"/>`
  const art = b.isSurprise
    ? `<text class="qm" x="${x + TILE / 2}" y="${y + TILE / 2 + 6}">?</text>`
    : `<use href="#${symbolOf(b.art, used)}" x="${x + 8}" y="${y + 8}" width="24" height="24" shape-rendering="crispEdges"${b.isEarned ? '' : ' opacity=".28"'}/>`
  return `<g class="${kind}" id="b${i}" aria-label="${esc(b.name)}">${frame}${art}</g>`
}

/** The hover note: a box with the badge's name, what it asks, and whether it is earned. */
const TIP_WIDTH = 216
const TIP_CHARS = 32
const TIP_PAD = 9
const TIP_LINE = 16

/** Words in lines of at most `chars` characters. */
function wrap(text: string, chars: number): string[] {
  const lines: string[] = []
  for (const word of text.split(' ')) {
    const last = lines.at(-1)
    if (last !== undefined && last.length + 1 + word.length <= chars) lines[lines.length - 1] = `${last} ${word}`
    else lines.push(word)
  }
  return lines
}

/**
 * A badge's note, there at once when the pointer is over it, where a title
 * would wait a second or more. Under the badge, or over it at the foot of the
 * wall, and kept inside it.
 */
function tip(b: Badge, i: number, x: number, y: number, width: number, height: number): string {
  const says = b.isSurprise ? ['Still a secret.'] : wrap(b.text, TIP_CHARS)
  const lines = [
    { text: b.name, cls: 'tn' },
    ...says.map(text => ({ text, cls: 'tt' })),
    ...(b.isEarned ? [{ text: 'Earned', cls: 'te' }] : []),
  ]
  const h = TIP_PAD * 2 + lines.length * TIP_LINE - 2
  const left = Math.max(0, Math.min(width - TIP_WIDTH, x + TILE / 2 - TIP_WIDTH / 2))
  const below = y + TILE + 6
  const top = below + h <= height ? below : Math.max(0, y - 6 - h)
  const text = lines
    .map((l, n) => `<tspan class="${l.cls}" x="${left + TIP_PAD + 1}" y="${top + TIP_PAD + 11 + n * TIP_LINE}">${esc(l.text)}</tspan>`)
    .join('')
  return `<g class="tip" id="t${i}"><rect x="${left + 0.5}" y="${top + 0.5}" width="${TIP_WIDTH - 1}" height="${h - 1}" rx="7"/><text>${text}</text></g>`
}

/**
 * Every badge, by group, in one picture: earned ones framed in gold, the rest
 * greyed, a surprise a dashed "?". Drawn interactive, so a pointer over a
 * badge rings it and opens its note at once. An interactive picture is drawn
 * in a frame, which takes the size it is given and no other: so the wall says
 * its own.
 */
export function badgeWall(groups: ShopModel['badges']['groups']): { source: string; width: number; height: number } {
  const width = WALL_WIDTH
  const cols = PER_ROW
  const used = new Map<string, string>()
  const labels: string[] = []
  const placed: { b: Badge; x: number; y: number }[] = []
  let y = 0
  for (const g of groups) {
    const won = g.items.filter(b => b.isEarned).length
    labels.push(`<text class="t" x="0" y="${y + 13}">${esc(g.title)} <tspan class="n">${won}/${g.items.length}</tspan></text>`)
    y += 20
    g.items.forEach((b, i) => placed.push({ b, x: (i % cols) * (TILE + GAP), y: y + Math.floor(i / cols) * (TILE + GAP) }))
    y += Math.ceil(g.items.length / cols) * (TILE + GAP) + 8
  }
  const height = Math.max(1, y - 8)
  const tiles = placed.map((p, i) => tile(p.b, i, p.x, p.y, used))
  // The notes come after every badge, so one is drawn over the badges below it,
  // and each opens from its own badge, a sibling before it.
  const tips = placed.map((p, i) => tip(p.b, i, p.x, p.y, width, height))
  const style =
    '<style>' +
    // A frame that sets the picture in a page of its own gives that page a margin: none here.
    'html,body{margin:0;padding:0;overflow:hidden}svg{display:block}' +
    `.t{font:12.5px system-ui,-apple-system,sans-serif;fill:#8a8880}.n{opacity:.75}` +
    `.f{fill:${GREY_FILL};stroke:${GREY_LINE};stroke-width:1}` +
    `.won .f{fill:rgba(242,182,50,.16);stroke:${GOLD};stroke-width:1.5}` +
    `.q .f{stroke-dasharray:3 3}` +
    `.qm{font:700 17px system-ui,-apple-system,sans-serif;fill:rgba(128,128,128,.85);text-anchor:middle}` +
    `.b:hover .f{stroke:${HOVER};stroke-width:1.5}` +
    // The notes: dark on either theme, as a system's own are.
    '.tip{opacity:0;visibility:hidden;pointer-events:none;transition:opacity .08s}' +
    '.tip rect{fill:#2b2a27;stroke:#4a4945}' +
    '.tip text{font:12px system-ui,-apple-system,sans-serif}' +
    '.tn{font-weight:700;fill:#f5f4ef}.tt{fill:#c9c6bb}.te{fill:#f2b632;font-weight:600}' +
    placed.map((_, i) => `#b${i}:hover~#t${i}`).join(',') +
    '{opacity:1;visibility:visible}' +
    '</style>'
  const defs = [...used].map(([id, body]) => `<symbol id="${id}" viewBox="0 0 12 12">${body}</symbol>`).join('')
  return { source: svg(width, height, `${style}<defs>${defs}</defs>${labels.join('')}${tiles.join('')}${tips.join('')}`), width, height }
}

files.hooks/scene.ts:
// The mine above the prompt, drawn pixel by pixel. One picture, two outputs:
// an SVG whose own CSS animates it (desktop), and Raster cells, two pixels to
// a cell, that a timer repaints (terminal).
//
// While Claude works the miner digs an endless tunnel. He stays where he is
// and the camera follows him: each swing the world slides CUT pixels left,
// fresh rock comes in from the right, and what he dug falls behind him with
// its timbers, lanterns and spoil heaps. The world repeats every PERIOD
// pixels, so when the slide wraps around the picture is the same and the loop
// never shows a seam.

import type { FindId, Mode, Season } from '../types'

export const W = 64
export const H = 24
/** Terminal rows: each cell is an upper half block, so two pixels tall. */
export const ROWS = H / 2

const CLEAR = -1

/** `pick` is the miner's pick, 0 worn iron to 4 obsidian, as the pick upgrades make it. */
export type SceneSpec = {
  mode: Mode
  carts: number
  goblins: number
  pick: number
  biome: number
  /** A bug on the rock while tests fail, or the splat where the pick got it. */
  bug?: 'crawl' | 'splat'
  /** What upgrades bought, there to see: a caged canary, work gloves, warmer lanterns, a coffee mug. */
  canary?: boolean
  gloves?: boolean
  warm?: boolean
  coffee?: boolean
  /** Claude asked to ultrathink: the lanterns flare. */
  flare?: boolean
  /** A find on the rock, there to catch. */
  find?: FindId
  /** A pumpkin on the cart the last week of October; a Santa hat, and snow on the topsoil, in December. */
  season?: Season
  /** A pull request merged: confetti falls for a moment. */
  confetti?: boolean
  /**
   * How the miner stands still: facing you while Claude asks, tipping his
   * helmet when thanked, with a coffee a while into Claude's idle, asleep after a long one.
   */
  pose?: 'facing' | 'tip' | 'coffee' | 'sleep'
}

/** One pose of the miner: `t` runs from the strike (0) to the raised pick (1); null rests. */
export type Frame = { at: number; t: number | null; bob: number; chips: boolean }

export const SWING_MS = 900
export const IMPACT_AT = 0.64
export const SWING: readonly Frame[] = [
  { at: 0, t: 0.3, bob: 0, chips: false },
  { at: 0.1, t: 0.6, bob: 0, chips: false },
  { at: 0.2, t: 0.85, bob: 0, chips: false },
  { at: 0.3, t: 1, bob: 0, chips: false },
  { at: 0.56, t: 0.5, bob: 0, chips: false },
  { at: IMPACT_AT, t: 0, bob: 1, chips: true },
  { at: 0.76, t: 0, bob: 0, chips: false },
]

export const REST_MS = 1600
export const REST: readonly Frame[] = [
  { at: 0, t: null, bob: 0, chips: false },
  { at: 0.5, t: null, bob: 1, chips: false },
]

/** Pixels the world slides per swing, and the width after which it repeats. */
export const CUT = 2
export const PERIOD = 32
/** Swings in one loop of the slide. */
export const CUTS = PERIOD / CUT
export const LOOP_MS = SWING_MS * CUTS
/** Every this many swings the pick strikes ore and sparkles. */
const SPARK_EVERY = 4
const SPARK_FOR = 0.25
const WHEEL_MS = 450

const cutAt = (k: number) => (k + IMPACT_AT) / CUTS

export function framesFor(mode: Mode): { frames: readonly Frame[]; ms: number } {
  if (mode === 'work') return { frames: SWING, ms: SWING_MS }
  if (mode === 'pause') return { frames: REST.slice(0, 1), ms: REST_MS }
  return { frames: REST, ms: REST_MS }
}

const mod = (n: number, m: number) => ((n % m) + m) % m

/** Which of `frames` shows at `share` (0 to 1) of its loop. */
export function frameIndex(frames: readonly Frame[], share: number): number {
  let index = 0
  frames.forEach((frame, i) => {
    if (frame.at <= share) index = i
  })
  return index
}

/** Everything that moves, `ms` into the animation. */
export type Moment = { frame: number; scroll: number; spark: boolean; wheel: number }

export function momentAt(mode: Mode, ms: number): Moment {
  if (mode !== 'work') {
    const { frames, ms: loop } = framesFor(mode)
    return { frame: frameIndex(frames, mod(ms, loop) / loop), scroll: 0, spark: false, wheel: 0 }
  }
  const at = mod(ms, LOOP_MS)
  const swing = Math.floor(at / SWING_MS)
  const within = (at - swing * SWING_MS) / SWING_MS
  const cuts = swing + (within >= IMPACT_AT ? 1 : 0)
  return {
    frame: frameIndex(SWING, within),
    scroll: mod(cuts * CUT, PERIOD),
    spark: swing % SPARK_EVERY === SPARK_EVERY - 1 && within >= IMPACT_AT && within < IMPACT_AT + SPARK_FOR,
    wheel: Math.floor(mod(ms, WHEEL_MS * 2) / WHEEL_MS),
  }
}

export const momentKey = (m: Moment) => `${m.frame}:${m.scroll}:${m.spark ? 1 : 0}:${m.wheel}`

class Pixels {
  readonly w: number
  readonly h: number
  data: Int32Array

  constructor(w = W, h = H, from?: Pixels) {
    this.w = w
    this.h = h
    this.data = from ? from.data.slice() : new Int32Array(w * h).fill(CLEAR)
  }

  copy(): Pixels {
    return new Pixels(this.w, this.h, this)
  }

  set(x: number, y: number, color: number): void {
    const px = Math.round(x)
    const py = Math.round(y)
    if (px >= 0 && px < this.w && py >= 0 && py < this.h) this.data[py * this.w + px] = color
  }

  get(x: number, y: number): number {
    if (x < 0 || x >= this.w || y < 0 || y >= this.h) return CLEAR
    return this.data[y * this.w + x] ?? CLEAR
  }

  /** Draws `over` on top, its clear pixels letting this one show. */
  stamp(over: Pixels): void {
    for (let y = 0; y < over.h; y += 1) {
      for (let x = 0; x < over.w; x += 1) {
        const color = over.get(x, y)
        if (color !== CLEAR) this.set(x, y, color)
      }
    }
  }

  line(x0: number, y0: number, x1: number, y1: number, color: number): void {
    let x = Math.round(x0)
    let y = Math.round(y0)
    const tx = Math.round(x1)
    const ty = Math.round(y1)
    const dx = Math.abs(tx - x)
    const dy = -Math.abs(ty - y)
    const sx = x < tx ? 1 : -1
    const sy = y < ty ? 1 : -1
    let err = dx + dy
    for (let i = 0; i < 256; i += 1) {
      this.set(x, y, color)
      if (x === tx && y === ty) break
      const e2 = 2 * err
      if (e2 >= dy) {
        err += dy
        x += sx
      }
      if (e2 <= dx) {
        err += dx
        y += sy
      }
    }
  }

  sprite(rows: readonly string[], palette: Readonly<Record<string, number>>, x: number, y: number): void {
    rows.forEach((row, dy) => {
      for (let dx = 0; dx < row.length; dx += 1) {
        const color = palette[row[dx] ?? '.']
        if (color !== undefined) this.set(x + dx, y + dy, color)
      }
    })
  }
}

function rng(seed: number): () => number {
  let s = seed | 0
  return () => {
    s = (s + 0x6d2b79f5) | 0
    let t = Math.imul(s ^ (s >>> 15), 1 | s)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const OUTLINE = 0x1d1512
const RAIL = 0x9aa3ad
const TIE = 0x5e3b1d
const WOOD = [0xa8743f, 0x8a5a2e, 0x5e3b1d] as const
const HANDLE = 0x9c6b3c
const STEEL = 0xaab4bf
const STEEL_LIGHT = 0xe6edf3
const STEEL_DARK = 0x6c7682
const LAMP = 0xfff4b8
const GLOW = 0xffc86e
const GOLD = [0xf2b632, 0xffe08a, 0xc7861d] as const
const TEAL = [0x5dcaa5, 0xb5f0dc, 0x1d9e75] as const
const SHIRT = 0xc2412d
const SKIN = 0xf0c08a

/** An ore's colors: its body, its glint and its shadow. */
type Ore = readonly [number, number, number]

/** The colors of one layer the mine digs through. */
type Strata = {
  cave: number
  caveDark: number
  caveLight: number
  rock: readonly [number, number, number]
  ceiling: readonly [number, number, number]
  dirt: number
  dirtSpeck: number
  pebble: number
  pile: number
  pileTop: number
  /** The two ores in the rock: the first is the one the pick throws sparks of. */
  ores: readonly [Ore, Ore]
  /** Daylight where the tunnel's back wall would be: the far side, out through the planet. */
  sky?: Sky
}

/**
 * The far side's sky, seen upside down: its bands from the top row down, palest
 * by the turf overhead, the clouds' color, the sun low in the frame, and the turf.
 */
type Sky = {
  bands: readonly (readonly [number, number])[]
  cloud: number
  sun: readonly [number, number]
  turf: readonly [number, number, number]
}

/**
 * Deeper is stranger: the mine passes from topsoil through stone, ancient ruins
